  {q:'Wie ist die Stelle vertraglich geregelt?',a:'Befristet auf zwei Jahre, mit dem Ziel einer Entfristung.',
   o:['Unbefristet ab dem ersten Tag.','Als Praktikum für ein Jahr.','Auf Honorarbasis ohne festen Vertrag.'],
   ex:'„Die Stelle ist zunächst auf zwei Jahre befristet, eine Entfristung wird angestrebt.“'},
  {q:'Welche Aufgabe gehört laut Anzeige zur Stelle?',a:'Fördermittel beantragen und den Geldgebern berichten.',
   o:['Die Buchhaltung des Vereins führen.','Das Gebäude instand halten.','Die Öffentlichkeitsarbeit der Stadt übernehmen.'],
   ex:'„Die Beantragung von Fördermitteln und die Berichterstattung an die Geldgeber liegen ebenfalls in Ihrer Verantwortung.“'},
  {q:'Was gilt für Bewerber ohne passendes Studium?',a:'Mehrjährige Berufserfahrung kann das Studium ersetzen.',
   o:['Sie werden nicht berücksichtigt.','Sie müssen das Studium nachholen.','Sie erhalten eine geringere Vergütung.'],
   ex:'„oder eine vergleichbare Qualifikation, die durch mehrjährige Berufserfahrung erworben wurde“'},
  {q:'Welche Sprachkenntnisse werden gefordert?',a:'Sicheres Deutsch; eine weitere Sprache ist erwünscht.',
   o:['Deutsch und Englisch sind beide Pflicht.','Zwei Fremdsprachen sind Voraussetzung.','Es werden keine Sprachkenntnisse genannt.'],
   ex:'„sicheres Deutsch in Wort und Schrift ... Kenntnisse in einer weiteren Sprache sind erwünscht, aber keine Bedingung“'},
  {q:'Was soll die Bewerbung enthalten?',a:'Einen Lebenslauf und ein Motivationsschreiben von maximal einer Seite.',
   o:['Nur ein Anschreiben, per Post geschickt.','Zeugnisse und drei Referenzen.','Ein kurzes Video zur Vorstellung.'],
   ex:'„Bewerbungen mit Lebenslauf und einem kurzen Motivationsschreiben – bitte nicht mehr als eine Seite“'}
